package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class DrawableWrapper extends Drawable implements Drawable.Callback { private Drawable child; public DrawableWrapper(Drawable d){setDrawable(d);} public Drawable getDrawable(){return child;} public void setDrawable(Drawable d){child=d;if(d!=null){d.setCallback(this);d.setBounds(getBounds());}} public void draw(Canvas c){if(child!=null)child.draw(c);} protected void onBoundsChange(Rect r){if(child!=null)child.setBounds(r);} protected boolean onStateChange(int[] s){return child!=null&&child.setState(s);} protected boolean onLevelChange(int l){return child!=null&&child.setLevel(l);} public int getIntrinsicWidth(){return child==null?-1:child.getIntrinsicWidth();} public int getIntrinsicHeight(){return child==null?-1:child.getIntrinsicHeight();} public void invalidateDrawable(Drawable d){invalidateSelf();} public void scheduleDrawable(Drawable d,Runnable r,long t){scheduleSelf(r,t);} public void unscheduleDrawable(Drawable d,Runnable r){unscheduleSelf(r);} }